import re, pickle
BASE = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/10_cluster/C7/public/snapshots/s14"
with open('handler_locks.pkl','rb') as f:
    handler_locks = pickle.load(f)

def base(expr):
    e = expr.strip().rstrip(';')
    return e.split('->')[-1].split('.')[-1].strip()

re_spin_plain = re.compile(r'\bspin_lock\s*\(\s*&?([^),]+)')
re_deffn = re.compile(r'^[A-Za-z_][A-Za-z0-9_ \t\*]*\(')

def fn_defs(lines):
    defs = []  # (lineno, name)
    for i, l in enumerate(lines):
        if re.match(r'^[A-Za-z_]', l) and '(' in l and not l.strip().endswith(';'):
            m = re.match(r'^.*?([A-Za-z_][A-Za-z0-9_]*)\s*\(', l)
            if m:
                nm = m.group(1)
                if nm in ('if','for','while','switch','return','sizeof'): continue
                defs.append((i+1, nm, l.strip()[:70]))
    return defs

rows = []
for path, hs in handler_locks.items():
    try:
        with open(path,'r',errors='replace') as fh:
            lines = fh.read().split('\n')
    except Exception:
        continue
    defs = fn_defs(lines)
    def enclosing(lineno):
        best = ('?', '?')
        for (dl, nm, txt) in defs:
            if dl <= lineno:
                best = (nm, txt)
            else:
                break
        return best
    rel = path.replace(BASE+'/','')
    for h, info in hs.items():
        plains = [x for x in info['locks'] if x[1]=='plain']
        if not plains: continue
        s_, e_ = info['range']
        hlock_bases = set(base(x[2]) for x in plains)
        matches = []
        for i, l in enumerate(lines):
            if s_-1 <= i < e_: continue
            m = re_spin_plain.search(l)
            if m and not re.search(r'\bspin_lock_bh\b|\bspin_lock_irq\b|\bspin_lock_irqsave\b', l):
                if base(m.group(1)) in hlock_bases:
                    matches.append((i+1, m.group(1).strip(), l.strip()[:90], enclosing(i+1)))
        if matches:
            hplains = [(x[0], x[2]) for x in plains]
            rows.append((rel, h, info['irq_line'], s_, e_, hlock_bases, hplains, matches))

rows.sort(key=lambda r: -len(r[7]))
for rel, h, irq, s_, e_, bases, hplains, matches in rows:
    print(f"### {rel}  handler={h} reg@{irq} def:{s_}-{e_} locks={sorted(bases)}")
    print(f"    handler-plain: {hplains[:4]}")
    for (lno, expr, txt, fn) in matches:
        print(f"    NH {lno:5d} {fn[0]:32s} {txt[:80]}")
PYEOF

